
/* ============================================================
   Claim workspace: overview, documents, review, normalization,
   tariff match, variances, claim update, audit
   ============================================================ */
function viewClaim(el, c, tab){
  setHeader(c.id,[{t:'Claims',href:'#/claims'},{t:c.id}]);
  const t=claimTotals(c); const exc=computeExceptions().filter(x=>x.claimId===c.id); const lowF=c.docs.reduce((s,d)=>s+d.fields.filter(x=>!x.verified&&x.conf<RULES.confidenceThreshold).length,0);
  const tabs=[['overview','Overview'],['documents','Documents',c.docs.length],['review','Review & correct',lowF,lowF>0],['normalization','Normalized data'],['tariff','Tariff match'],['variances','Variances',t.variances.filter(v=>v.decision.status==='Open').length,t.open>0],['update','Claim update'],['audit','Audit trail',c.audit.length]];
  el.innerHTML=`
  <div class="card mb"><div class="card-body" style="display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;align-items:flex-start">
    <div><div class="row" style="gap:10px"><span style="font-size:18px;font-weight:600">${esc(c.patient)}</span>${statusBadge(c.status)}<span class="badge b-gray">${c.claimType}</span><span class="badge b-gray">${c.lob}</span></div>
      <div class="small muted" style="margin-top:4px">${c.memberId} · Policy ${c.policy} · ${esc(c.hospital)} · Admitted ${c.admission} → ${c.discharge} · via ${c.source} ${ago(c.receivedAt)} ago · Assignee: ${esc(userName(c.assignee))}</div></div>
    <div class="row" style="gap:20px"><div><div class="small muted">Billed</div><div class="strong" style="font-size:16px">${fmtINR(t.billed)}</div></div><div><div class="small muted">Flagged</div><div class="strong" style="font-size:16px;color:${t.flagged?'var(--red)':'inherit'}">${fmtINR(t.flagged)}</div></div><div><div class="small muted">Deductions accepted</div><div class="strong" style="font-size:16px">${fmtINR(t.accepted)}</div></div><div><div class="small muted">Payable (est.)</div><div class="strong" style="font-size:16px;color:var(--accent)">${fmtINR(t.payable)}</div></div></div>
  </div>${pipelineEl(c)}</div>
  <div class="tabs">${tabs.map(([k,l,n,w])=>`<a href="#/claims/${c.id}/${k}" class="${tab===k?'active':''}">${l}${n!=null?`<span class="cnt ${w?'warn':''}">${n}</span>`:''}</a>`).join('')}</div>
  <div id="tab-body"></div>`;
  const body=$('#tab-body',el);
  ({overview:tabOverview,documents:tabDocuments,review:tabReview,normalization:tabNormalization,tariff:tabTariff,variances:tabVariances,update:tabUpdate,audit:tabAudit}[tab]||tabOverview)(body,c);
}

/* ---- Overview ---- */
function tabOverview(el,c){
  const t=claimTotals(c); const exc=computeExceptions().filter(x=>x.claimId===c.id); const prim=c.diagnoses.find(d=>d.primary); const proc=c.procedures.find(p=>p.primary);
  const ver=tariffVersionForClaim(c);
  el.innerHTML=`<div class="grid g-2">
    <div class="stack">
      <div class="card"><div class="card-head"><h3>Clinical summary</h3><span class="small muted">From discharge summary & Form C</span></div><div class="card-body"><dl class="kv"><dt>Primary diagnosis</dt><dd>${prim?esc(prim.text)+' <span class="hl-code">'+prim.icd+'</span>':'—'}</dd><dt>Primary procedure</dt><dd>${proc?esc(proc.text)+' <span class="hl-code">'+proc.pcs+'</span>':'Medical management'}</dd><dt>Treatment type</dt><dd>${c.facts.surgical?'Surgical':'Medical'}</dd><dt>Stay</dt><dd>${c.admission} → ${c.discharge} (${c.facts.los} day${c.facts.los>1?'s':''}, ICU ${c.facts.icuDays})</dd><dt>ICP summary</dt><dd style="font-weight:400">${esc(c.icpSummary)}</dd></dl></div></div>
      <div class="card"><div class="card-head"><h3>Open exceptions</h3><a class="btn btn-ghost btn-sm" href="#/queue">Work queue</a></div>${exc.length?`<div class="table-wrap"><table class="tbl"><tbody>${exc.map(x=>`<tr class="clickable" data-go="${esc(x.link)}"><td>${prioBadge(x.priority)}</td><td>${esc(x.type)}<div class="small muted">${esc(x.issue)}</div></td><td>${slaBadge(x)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No open exceptions</strong>All fields validated and all variances decided.</div>'}</div>
    </div>
    <div class="stack">
      <div class="card"><div class="card-head"><h3>Financial summary</h3><span class="small muted">${ver?ver.id+' · effective '+ver.effectiveFrom:'No tariff version'}</span></div><div class="card-body"><dl class="kv"><dt>Total billed</dt><dd>${fmtINR(t.billed)}</dd><dt>Non-medical (excluded)</dt><dd>${fmtINR(t.nonMed)}</dd><dt>Variances flagged</dt><dd style="color:var(--red)">${fmtINR(t.flagged)} (${t.variances.length})</dd><dt>Deductions accepted</dt><dd>${fmtINR(t.accepted)}</dd><dt>Awaiting decision</dt><dd>${fmtINR(t.open)}</dd><dt>Estimated payable</dt><dd style="color:var(--accent)">${fmtINR(t.payable)}</dd></dl></div></div>
      <div class="card"><div class="card-head"><h3>Documents</h3><a class="btn btn-ghost btn-sm" href="#/claims/${c.id}/documents">Open</a></div><div class="table-wrap"><table class="tbl"><tbody>${c.docs.map(d=>`<tr><td>${esc(d.type)}<div class="small muted">${esc(d.name)} · ${d.pages.length} page${d.pages.length>1?'s':''}</div></td><td class="right">${d.ocrStatus==='Completed'?(d.validated?'<span class="badge b-green">Validated</span>':'<span class="badge b-teal">Extracted</span>'):'<span class="badge b-amber">'+esc(d.ocrStatus)+'</span>'}</td></tr>`).join('')}</tbody></table></div></div>
      <div class="card"><div class="card-head"><h3>Recent activity</h3></div><div class="card-body"><ul class="timeline">${c.audit.slice(0,5).map(a=>`<li>${esc(a.user)} · ${esc(a.entity)} ${esc(a.action.toLowerCase())}<small>${esc(a.detail)} · ${fmtDT(a.ts)}</small></li>`).join('')}</ul></div></div>
    </div></div>`;
  $$('[data-go]',el).forEach(r=>r.onclick=()=>go(r.dataset.go));
}

/* ---- Documents & classification ---- */
function tabDocuments(el,c){
  const q=STATE.route.query; let sel=c.docs.find(d=>d.id===q.doc)||c.docs[0];
  const draw=()=>{
    el.innerHTML=`<div class="split-list" style="grid-template-columns:340px 1fr">
      <div class="stack"><div class="card"><div class="card-head"><h3>Documents</h3><span class="small muted">${c.docs.filter(d=>d.medical).length} medical · ${c.docs.filter(d=>!d.medical).length} non-medical</span></div><div class="list-nav">${c.docs.map(d=>`<button class="${d.id===sel.id?'active':''}" data-doc="${d.id}"><div class="row" style="justify-content:space-between"><span>${esc(d.type)}</span>${d.ocrStatus!=='Completed'?'<span class="badge b-amber">Queued</span>':d.validated?'<span class="badge b-green">Validated</span>':''}</div><small>${esc(d.name)} · ${d.size} · ${d.pages.length} page${d.pages.length>1?'s':''}${d.handwritten?' · handwritten':''}</small></button>`).join('')}</div></div>
      ${can('upload')?`<button class="btn btn-outline" id="add-doc">Add documents to this claim</button>`:''}
      ${c.ocrFallback&&c.ocrFallback.queued?`<div class="callout warn"><div><strong>OCR fallback queued.</strong> ${esc(c.ocrFallback.reason)}. The document will be re-extracted by the fallback OCR engine and routed for manual validation.<div class="mt" style="margin-top:8px"><button class="btn btn-outline btn-sm" id="retry-ocr">Retry now</button></div></div></div>`:''}</div>
      <div class="stack">
        <div class="card"><div class="card-head"><div><h3>${esc(sel.type)} <span class="sub">${esc(sel.name)}</span></h3></div><div class="row"><span class="badge b-gray">${sel.ext.toUpperCase()} · ${sel.size}</span><span class="badge b-gray">${esc(sel.language)}</span>${sel.handwritten?'<span class="badge b-amber">Handwritten</span>':''}<span class="badge ${sel.medical?'b-teal':'b-gray'}">${sel.medical?'Medical':'Non-medical'}</span></div></div>
        <div class="card-body"><div class="grid g-3">
          <div><div class="small muted">Source</div><div class="strong">${esc(sel.source)}</div></div><div><div class="small muted">OCR status</div><div class="strong">${esc(sel.ocrStatus)}</div></div><div><div class="small muted">Fields extracted</div><div class="strong">${sel.fields.length} · ${sel.fields.filter(f=>f.conf<RULES.confidenceThreshold&&!f.verified).length} need validation</div></div>
        </div>
        <div class="mt"><div class="small muted mb" style="margin-bottom:6px">Detections</div><div class="detect">${['stamp','signature','logo'].map(k=>`<span class="badge ${sel.detections.includes(k)?'b-green':'b-gray'}">${k[0].toUpperCase()+k.slice(1)} ${sel.detections.includes(k)?'detected':'not found'}</span>`).join('')}<span class="badge ${sel.pages.length>1?'b-blue':'b-gray'}">${sel.pages.length>1?'Multi-page':'Single page'}</span>${BILL_TYPES.includes(sel.type)?'<span class="badge b-blue">Tabular content</span>':''}</div></div></div></div>
        <div class="card"><div class="card-head"><h3>Page classification</h3><span class="small muted">Each page classified independently; response < 1 s</span><div class="row">${can('review')?`<button class="btn btn-outline btn-sm" id="reclass">Reclassify document</button>`:''}</div></div>
        <div class="table-wrap"><table class="tbl"><thead><tr><th>Page</th><th>Classified as</th><th>Confidence</th><th>Orientation</th><th>Layout</th><th></th></tr></thead><tbody>${sel.pages.map(p=>`<tr><td>${p.n}</td><td>${esc(p.label)}</td><td>${confEl(p.conf)}</td><td class="small">${p.n===2&&sel.handwritten?'Rotated 90° → corrected':'Portrait'}</td><td class="small">${BILL_TYPES.includes(sel.type)?'Table (merged cells handled)':sel.type.includes('Form')?'Form / key-value':'Text + table'}</td><td class="right">${can('review')?`<button class="btn btn-ghost btn-sm" data-page="${p.n}">Change</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>
        <div class="card"><div class="card-head"><h3>Preview</h3><a class="btn btn-primary btn-sm" href="#/claims/${c.id}/review?doc=${sel.id}">Review extracted fields</a></div><div class="doc-page" style="min-height:360px">${paperEl(sel,c,null,1)}</div></div>
      </div></div>`;
    $$('[data-doc]',el).forEach(b=>b.onclick=()=>{ sel=c.docs.find(d=>d.id===b.dataset.doc); history.replaceState(null,'','#/claims/'+c.id+'/documents?doc='+sel.id); draw(); });
    const add=$('#add-doc',el); if(add) add.onclick=()=>{ const fi=$('#file-input'); fi.value=''; fi.onchange=()=>{ const files=[...fi.files]; fi.value=''; const bad=files.map(f=>({f,err:validateFile(f)})).filter(x=>x.err); if(bad.length){ toast(bad[0].err,'bad'); } const ok=files.filter(f=>!validateFile(f)); if(ok.length){ attachFilesToClaim(c,ok,'Manual upload'); toast(ok.length+' document(s) added and classified','ok'); notify(`${ok.length} document(s) added to ${c.id}`,'ok','#/claims/'+c.id+'/documents'); render(); } }; fi.click(); };
    const rc=$('#reclass',el); if(rc) rc.onclick=()=>openModal({title:'Reclassify — '+sel.name, body:`<div class="field"><label>Document type</label><select id="rc-type">${DOC_TYPES.map(t=>`<option ${t===sel.type?'selected':''}>${t}</option>`).join('')}</select></div>`, footer:`<button class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary" id="rc-ok">Apply & re-extract</button>`, onOpen:m=>{ $('#rc-ok',m).onclick=()=>{ const nt=$('#rc-type',m).value; if(nt===sel.type){ closeModal(); return; } const before=sel.type; sel.type=nt; sel.medical=!NON_MEDICAL_DOCS.includes(nt); sel.pages.forEach(p=>{ p.cls=nt; p.label=nt+(sel.pages.length>1?' '+p.n:''); p.conf=100; }); sel.fields=fieldsFor(nt,c.facts); sel.validated=false; audit(c,'Document','Reclassified',`${sel.name}: ${before} → ${nt}`,before,nt); closeModal(); toast('Reclassified and re-extracted','ok'); render(); }; }});
    $$('[data-page]',el).forEach(b=>b.onclick=()=>{ const p=sel.pages.find(x=>x.n===+b.dataset.page); openModal({title:'Change page '+p.n+' classification', body:`<div class="field"><label>Classified as</label><select id="pc-type">${DOC_TYPES.map(t=>`<option ${t===p.cls?'selected':''}>${t}</option>`).join('')}</select></div>`, footer:`<button class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary" id="pc-ok">Save</button>`, onOpen:m=>{ $('#pc-ok',m).onclick=()=>{ const before=p.cls; p.cls=$('#pc-type',m).value; p.label=p.cls+' (p'+p.n+')'; p.conf=100; audit(c,'Document','Page reclassified',`${sel.name} page ${p.n}: ${before} → ${p.cls}`,before,p.cls); closeModal(); toast('Page classification updated','ok'); draw(); }; }}); });
    const ro=$('#retry-ocr',el); if(ro) ro.onclick=async()=>{ ro.disabled=true; ro.textContent='Re-running OCR…'; await sleep(1200); c.ocrFallback.queued=false; c.docs.forEach(d=>{ if(d.ocrStatus!=='Completed'){ d.ocrStatus='Completed (fallback OCR)'; d.fields.forEach(f=>f.conf=Math.max(60,f.conf-8)); } }); c.stage=6; const vs=computeVariances(c); c.status=vs.length?'Variance review':'In review'; c.assignee=c.assignee||STATE.user.id; audit(c,'Document','OCR fallback completed','Lab_Report.tif re-extracted with fallback engine; fields routed for validation'); notify(`Fallback OCR completed for ${c.id}; claim moved to ${c.status}`,'ok','#/claims/'+c.id+'/review'); toast('Fallback OCR complete','ok'); render(); };
  };
  draw();
}

/* ---- Paper (document preview) ---- */
function paperEl(d,c,selField,page){
  const secs={}; d.fields.forEach(f=>{ (secs[f.section]=secs[f.section]||[]).push(f); });
  const names=Object.keys(secs); const per=Math.ceil(names.length/d.pages.length)||1; const pageSecs=names.slice((page-1)*per,page*per);
  const bill=BILL_TYPES.includes(d.type)?c.lineItems.filter(l=>l.bill===d.type):[];
  return `<div class="paper ${d.handwritten?'hand':''} scan">${d.detections.includes('logo')?'<div class="logo">'+esc(c.hospital.split(',')[0])+'</div>':''}<h4>${esc(d.type.toUpperCase())}${d.pages.length>1?' — PAGE '+page+' OF '+d.pages.length:''}</h4>
    ${pageSecs.map(s=>`<div class="ph">${esc(s)}</div>${secs[s].map(f=>`<div class="pf ${selField===f.id?'hl':''} ${f.conf<RULES.confidenceThreshold&&!f.verified?'lo':''}" data-pf="${f.id}"><b>${esc(f.label)}</b><span>${esc(f.value)}</span></div>`).join('')}`).join('')}
    ${bill.length&&page===d.pages.length?`<div class="ph">Line items</div><table><tr><th>Particular</th><th>Qty</th><th>Rate</th><th>Net</th></tr>${bill.slice(0,8).map(l=>`<tr><td>${esc(l.desc)}</td><td>${l.qty}</td><td>${l.unitPrice}</td><td>${l.net}</td></tr>`).join('')}${bill.length>8?`<tr><td colspan="4">… ${bill.length-8} more</td></tr>`:''}</table>`:''}
    ${d.detections.includes('stamp')&&page===d.pages.length?`<div class="stamp">${esc(c.hospital.split(',')[0])}<br>SEAL</div>`:''}${d.detections.includes('signature')&&page===d.pages.length?`<div class="sig">${esc(c.facts.doctor.replace('Dr. ',''))}</div>`:''}</div>`;
}

/* ---- Review & correct ---- */
function tabReview(el,c){
  const q=STATE.route.query; const st=STATE.reviewSel[c.id]=STATE.reviewSel[c.id]||{doc:null,field:null,page:1,onlyLow:false,editing:null};
  if(q.doc) st.doc=q.doc; if(q.field) st.field=q.field;
  let doc=c.docs.find(d=>d.id===st.doc)||c.docs.find(d=>d.fields.some(f=>f.conf<RULES.confidenceThreshold&&!f.verified))||c.docs[0]; st.doc=doc.id;
  if(st.field && !doc.fields.some(f=>f.id===st.field)) st.field=null;
  const draw=()=>{
    const low=doc.fields.filter(f=>!f.verified&&f.conf<RULES.confidenceThreshold).length;
    const secs={}; doc.fields.forEach(f=>{ if(st.onlyLow&&(f.verified||f.conf>=RULES.confidenceThreshold)) return; (secs[f.section]=secs[f.section]||[]).push(f); });
    if(st.field){ const names=Object.keys(doc.fields.reduce((o,f)=>(o[f.section]=1,o),{})); const per=Math.ceil(names.length/doc.pages.length)||1; const f=doc.fields.find(x=>x.id===st.field); st.page=Math.floor(names.indexOf(f.section)/per)+1; }
    el.innerHTML=`<div class="row mb" style="justify-content:space-between"><div class="row"><div class="field"><label>Document</label><select id="rv-doc">${c.docs.map(d=>{ const n=d.fields.filter(f=>!f.verified&&f.conf<RULES.confidenceThreshold).length; return `<option value="${d.id}" ${d.id===doc.id?'selected':''}>${esc(d.type)} — ${esc(d.name)}${n?' ('+n+' to validate)':''}</option>`; }).join('')}</select></div><label class="toggle" style="margin-top:18px"><input type="checkbox" id="rv-low" ${st.onlyLow?'checked':''}>Show only fields below ${RULES.confidenceThreshold}%</label></div>
      <div class="callout ${low?'warn':'ok'}" style="padding:8px 12px"><div>${low?`<strong>${low} field${low>1?'s':''}</strong> in this document ${low>1?'are':'is'} below the ${RULES.confidenceThreshold}% threshold and must be validated or corrected.`:'<strong>All fields validated</strong> for this document.'}</div></div></div>
    <div class="viewer">
      <div class="card"><div class="card-head"><div class="page-nav"><button class="btn btn-outline btn-sm" id="pg-prev" ${st.page<=1?'disabled':''}>‹</button><span>Page ${st.page} of ${doc.pages.length}</span><button class="btn btn-outline btn-sm" id="pg-next" ${st.page>=doc.pages.length?'disabled':''}>›</button><span class="small muted" style="margin-left:8px">${esc(doc.pages[st.page-1].label)} · ${doc.pages[st.page-1].conf}%</span></div><div class="row"><span class="badge b-gray">${doc.handwritten?'Handwritten · NLP autocorrect on':'Printed'}</span>${doc.masked?'':''}</div></div><div class="doc-page">${paperEl(doc,c,st.field,st.page)}</div></div>
      <div class="card" style="display:flex;flex-direction:column"><div class="card-head"><h3>Extracted fields <span class="sub">${doc.fields.length} · click a field to locate it on the page</span></h3></div>
        <div class="fields-list">${Object.keys(secs).length?Object.entries(secs).map(([s,fs])=>`<div class="fsec">${esc(s)}</div>${fs.map(f=>fieldItem(f)).join('')}`).join(''):'<div class="empty">No fields below threshold in this document.</div>'}</div>
        <div class="row" style="padding:12px 14px;border-top:1px solid var(--line);justify-content:space-between"><span class="small muted">${doc.validated?'<span class="badge b-green">Document validated</span>':low?'Resolve low-confidence fields to validate':'Ready to validate'}</span>${can('review')?`<button class="btn btn-accent" id="validate-doc" ${low||doc.validated?'disabled':''}>Validate document</button>`:''}</div></div>
    </div>`;
    function fieldItem(f){ const editing=st.editing===f.id; return `<div class="fitem ${st.field===f.id?'sel':''}" data-fid="${f.id}"><div class="fl"><span>${esc(f.label)}${f.masked?' <span class="badge b-gray">masked</span>':''}${f.detect?' <span class="badge b-teal">'+f.detect+'</span>':''}</span>${confEl(f.conf,f.verified)}</div>
      ${editing?`<div class="edit"><input id="ed-in" value="${esc(f.value)}" aria-label="Edit ${esc(f.label)}"><div class="err" id="ed-err"></div><div class="row"><button class="btn btn-primary btn-sm" id="ed-save">Save correction</button><button class="btn btn-outline btn-sm" id="ed-cancel">Cancel</button></div><div class="small muted">Original OCR: ${esc(f.original)}</div></div>`
      :`<div class="fv ${f.value!==f.original?'edited':''}">${esc(f.value)}${f.value!==f.original?` <span class="small muted">(was ${esc(f.original)})</span>`:''}</div>${st.field===f.id&&can('review')&&!f.verified?`<div class="row" style="margin-top:8px"><button class="btn btn-success btn-sm" data-ok="${f.id}">Confirm as correct</button><button class="btn btn-outline btn-sm" data-edit="${f.id}">Correct value</button>${f.conf<RULES.confidenceThreshold&&can('escalate')?`<button class="btn btn-ghost btn-sm" data-esc="${f.id}">Escalate</button>`:''}</div>`:''}`}</div>`; }
    $('#rv-doc',el).onchange=e=>{ st.doc=e.target.value; st.field=null; st.page=1; st.editing=null; history.replaceState(null,'','#/claims/'+c.id+'/review?doc='+st.doc); tabReview(el,c); };
    $('#rv-low',el).onchange=e=>{ st.onlyLow=e.target.checked; draw(); };
    $('#pg-prev',el).onclick=()=>{ st.page--; st.field=null; draw(); }; $('#pg-next',el).onclick=()=>{ st.page++; st.field=null; draw(); };
    $$('.fitem',el).forEach(x=>x.onclick=e=>{ if(e.target.closest('button,input')) return; st.field=x.dataset.fid; st.editing=null; draw(); const pf=$(`[data-pf="${st.field}"]`,el); if(pf) pf.scrollIntoView({block:'center',behavior:'smooth'}); });
    $$('[data-pf]',el).forEach(p=>p.onclick=()=>{ st.field=p.dataset.pf; st.editing=null; draw(); const fi=$(`.fitem[data-fid="${st.field}"]`,el); if(fi) fi.scrollIntoView({block:'center',behavior:'smooth'}); });
    $$('[data-ok]',el).forEach(b=>b.onclick=()=>{ const f=doc.fields.find(x=>x.id===b.dataset.ok); f.verified=true; f.history.push({ts:new Date().toISOString(),user:STATE.user.name,action:'Confirmed'}); audit(c,'Field','Confirmed',`${f.label} = "${f.value}" (${f.conf}%) in ${doc.type}`,f.value,f.value); toast('Field confirmed','ok'); afterFieldChange(); });
    $$('[data-edit]',el).forEach(b=>b.onclick=()=>{ st.editing=b.dataset.edit; draw(); const i=$('#ed-in',el); if(i){ i.focus(); i.select(); } });
    $$('[data-esc]',el).forEach(b=>b.onclick=()=>{ const f=doc.fields.find(x=>x.id===b.dataset.esc); promptModal('Escalate field to Compliance','Reason',v=>{ c.escalations.push({id:uid('ESC'),ts:new Date().toISOString(),by:STATE.user.name,to:'Compliance',reason:`${f.label} in ${doc.type}: ${v}`,status:'Open',ref:f.label}); audit(c,'Exception','Escalated',`${f.label} → Compliance: ${v}`); notify(`${c.id}: ${f.label} escalated to Compliance`,'warn','#/queue'); toast('Escalated to Compliance','ok'); render(); },{placeholder:'e.g. Handwriting illegible even after zoom; need original from hospital.'}); });
    const sv=$('#ed-save',el); if(sv){ const f=doc.fields.find(x=>x.id===st.editing); const inp=$('#ed-in',el); const save=()=>{ const v=inp.value.trim(); const err=validateField(f,v); if(err){ $('#ed-err',el).textContent=err; inp.classList.add('invalid'); return; } const before=f.value; if(v!==before){ f.value=v; f.history.push({ts:new Date().toISOString(),user:STATE.user.name,before,after:v}); audit(c,'Field','Corrected',`${f.label} in ${doc.type}`,before,v); } f.verified=true; st.editing=null; toast('Correction saved and audited','ok'); afterFieldChange(); }; sv.onclick=save; inp.onkeydown=e=>{ if(e.key==='Enter') save(); if(e.key==='Escape'){ st.editing=null; draw(); } }; $('#ed-cancel',el).onclick=()=>{ st.editing=null; draw(); }; }
    const vd=$('#validate-doc',el); if(vd) vd.onclick=()=>{ doc.validated=true; audit(c,'Document','Validated',`${doc.type} (${doc.name}) validated by ${STATE.user.name}`); toast(doc.type+' validated','ok'); afterFieldChange(); };
    function afterFieldChange(){ if(c.status==='In review'){ const anyLow=c.docs.some(d=>d.fields.some(f=>!f.verified&&f.conf<RULES.confidenceThreshold)); if(!anyLow){ const vs=computeVariances(c); c.status=vs.length?'Variance review':'Approved'; c.stage=vs.length?5:7; notify(`${c.id}: all fields validated; moved to ${c.status}`,'ok','#/claims/'+c.id); } } render(); }
  };
  draw();
}
function validateField(f,v){
  if(!v) return 'Value cannot be empty.';
  const l=f.label.toLowerCase();
  if(/date|dob|birth/.test(l) && !/^\d{2}-\d{2}-\d{4}$/.test(v)) return 'Use DD-MM-YYYY (e.g. 15-03-1985).';
  if(/date|dob|birth/.test(l)){ const [d,m,y]=v.split('-').map(Number); if(m<1||m>12||d<1||d>31||y<1900||y>2100) return 'Not a valid calendar date.'; }
  if(/icd-10/.test(l) && v!=='—' && !/^[A-Z]\d{2}(\.\d{1,4}[A-Z]?)?$/.test(v)) return 'ICD-10 format is a letter, two digits, optional .subcode (e.g. K35.80).';
  if(/pcs code/.test(l) && v!=='—' && !/^[0-9A-HJ-NP-Z]{7}$/.test(v)) return 'ICD-10-PCS codes are exactly 7 alphanumeric characters with no spaces (e.g. 0DTJ4ZZ).';
  if(/contact|phone/.test(l) && !/^[\d\s+()-]{8,15}$/.test(v)) return 'Enter a valid phone number (8–15 digits).';
  if(/age/.test(l) && !/years|months/.test(l) && !/^\d{1,3}$/.test(v)) return 'Age must be a whole number.';
  if(/amount|cost|charges|gross|discount|total/.test(l) && !/^₹?\s?[\d,]+(\.\d{1,2})?$/.test(v)) return 'Enter an amount in INR, e.g. ₹1,45,000.';
  if(/email/.test(l) && !/^[^@\s]+@[^@\s]+\.[a-z]{2,}$/i.test(v)) return 'Enter a valid email address.';
  if(/gst/.test(l) && !/^\d{2}[A-Z]{5}\d{4}[A-Z]\d[A-Z\d]Z[A-Z\d]$/.test(v)) return 'GSTIN must be 15 characters, e.g. 33AAACA1234A1Z5.';
  return null;
}

/* ---- Normalized data ---- */
function tabNormalization(el,c){
  const draw=()=>{
    el.innerHTML=`<div class="grid g-2 mb">
      <div class="card"><div class="card-head"><h3>Diagnoses → ICD-10</h3><span class="small muted">Mapped to internal catalogue, level 3</span></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Diagnosis (as written)</th><th>ICD-10</th><th>Catalogue description</th><th>Confidence</th><th>Primary</th></tr></thead><tbody>${c.diagnoses.map((d,i)=>`<tr class="${d.primary?'flag':''}"><td>${esc(d.text)}</td><td><span class="hl-code">${d.icd}</span>${d.alt?`<div class="small muted">alt: ${d.alt.join(', ')}</div>`:''}</td><td class="small">${esc(ICD[d.icd]||'Not in catalogue')}</td><td>${confEl(Math.round(d.conf*100))}</td><td>${d.primary?'<span class="badge b-teal">Primary</span>':can('review')?`<button class="btn btn-ghost btn-sm" data-prim-dx="${i}">Set primary</button>`:''}</td></tr>`).join('')}</tbody></table></div>${can('review')?`<div class="card-body" style="border-top:1px solid var(--line-soft)"><button class="btn btn-outline btn-sm" id="add-dx">Add / remap diagnosis</button></div>`:''}</div>
      <div class="card"><div class="card-head"><h3>Procedures → ICD-10-PCS</h3></div>${c.procedures.length?`<div class="table-wrap"><table class="tbl"><thead><tr><th>Procedure (as written)</th><th>PCS</th><th>Catalogue description</th><th>Confidence</th><th>Primary</th></tr></thead><tbody>${c.procedures.map((p,i)=>`<tr class="${p.primary?'flag':''}"><td>${esc(p.text)}</td><td><span class="hl-code">${p.pcs}</span></td><td class="small">${esc(PCS[p.pcs]||'Not in catalogue')}</td><td>${confEl(Math.round(p.conf*100))}</td><td>${p.primary?'<span class="badge b-teal">Primary</span>':can('review')?`<button class="btn btn-ghost btn-sm" data-prim-px="${i}">Set primary</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No procedure</strong>Medical management — no PCS mapping required.</div>'}<div class="card-body" style="border-top:1px solid var(--line-soft)"><div class="small muted">ICP summary (auto-generated)</div><div style="margin-top:4px">${esc(c.icpSummary)}</div></div></div>
    </div>
    <div class="card"><div class="card-head"><h3>Structured line items <span class="sub">${c.lineItems.length} lines · currency normalized to INR · units standardized</span></h3><div class="row"><span class="badge b-teal">Medical ${fmtINR(c.lineItems.filter(l=>l.medical).reduce((s,l)=>s+l.net,0))}</span><span class="badge b-gray">Non-medical ${fmtINR(c.lineItems.filter(l=>!l.medical).reduce((s,l)=>s+l.net,0))}</span><button class="btn btn-outline btn-sm" id="exp-lines">Export CSV</button></div></div>
    <div class="table-wrap"><table class="tbl"><thead><tr><th>Bill</th><th>Particular</th><th>Code</th><th>Category</th><th class="num">Qty</th><th>Unit</th><th class="num">Unit price</th><th class="num">Gross</th><th class="num">Discount</th><th class="num">Net</th><th>P/NP</th><th>Batch / expiry</th><th>Date</th><th>Medical</th></tr></thead><tbody>${c.lineItems.map(l=>`<tr class="${l.medical?'':'dim'}"><td class="small">${esc(l.bill)}</td><td>${esc(l.desc)}${l.sticker?`<div class="small muted">Sticker ${l.sticker}</div>`:''}</td><td class="small">${l.code||'<span class="muted">—</span>'}</td><td class="small">${l.category}</td><td class="num">${l.qty}</td><td class="small">${l.unit}</td><td class="num">${fmtINR(l.unitPrice)}</td><td class="num">${fmtINR(l.gross)}</td><td class="num">${fmtINR(l.discount)}</td><td class="num strong">${fmtINR(l.net)}</td><td>${l.pnp}</td><td class="small">${l.batch||'—'}</td><td class="small">${l.date||'—'}</td><td>${can('review')?`<label class="toggle"><input type="checkbox" data-med="${l.id}" ${l.medical?'checked':''}></label>`:(l.medical?'Yes':'No')}</td></tr>`).join('')}</tbody></table></div></div>`;
    $$('[data-prim-dx]',el).forEach(b=>b.onclick=()=>{ const i=+b.dataset.primDx; const before=c.diagnoses.find(d=>d.primary); c.diagnoses.forEach(d=>d.primary=false); c.diagnoses[i].primary=true; audit(c,'Normalization','Primary diagnosis changed',`${before?before.icd:'—'} → ${c.diagnoses[i].icd}`,before&&before.icd,c.diagnoses[i].icd); toast('Primary diagnosis updated','ok'); draw(); });
    $$('[data-prim-px]',el).forEach(b=>b.onclick=()=>{ const i=+b.dataset.primPx; const before=c.procedures.find(d=>d.primary); c.procedures.forEach(d=>d.primary=false); c.procedures[i].primary=true; audit(c,'Normalization','Primary procedure changed',`${before?before.pcs:'—'} → ${c.procedures[i].pcs}`,before&&before.pcs,c.procedures[i].pcs); toast('Primary procedure updated','ok'); draw(); });
    $$('[data-med]',el).forEach(i=>i.onchange=()=>{ const l=c.lineItems.find(x=>x.id===i.dataset.med); l.medical=i.checked; audit(c,'Normalization','Line reclassified',`"${l.desc}" marked ${l.medical?'medical':'non-medical'}`,String(!l.medical),String(l.medical)); toast('Line item updated — payable recomputed','ok'); render(); });
    const ad=$('#add-dx',el); if(ad) ad.onclick=()=>openModal({title:'Add / remap diagnosis', body:`<div class="stack"><div class="field"><label>Diagnosis text</label><input id="dx-text" placeholder="As written in discharge summary"></div><div class="field"><label>ICD-10 code (catalogue)</label><select id="dx-code">${Object.entries(ICD).map(([k,v])=>`<option value="${k}">${k} — ${esc(v)}</option>`).join('')}</select></div><div class="err" id="dx-err" style="color:var(--red);font-size:12px"></div></div>`, footer:`<button class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary" id="dx-ok">Add</button>`, onOpen:m=>{ $('#dx-ok',m).onclick=()=>{ const t=$('#dx-text',m).value.trim(); if(t.length<3){ $('#dx-err',m).textContent='Enter the diagnosis text.'; return; } const code=$('#dx-code',m).value; c.diagnoses.push({text:t,icd:code,conf:1,primary:!c.diagnoses.length,manual:true}); audit(c,'Normalization','Diagnosis added',`${t} → ${code}`); closeModal(); toast('Diagnosis mapped','ok'); draw(); }; }});
    $('#exp-lines',el).onclick=()=>exportCSV(c.id+'_line_items.csv',[['Bill','Particular','Code','Category','Qty','Unit','Unit price','Gross','Discount','Net','P/NP','Batch','Date','Medical']].concat(c.lineItems.map(l=>[l.bill,l.desc,l.code||'',l.category,l.qty,l.unit,l.unitPrice,l.gross,l.discount,l.net,l.pnp,l.batch||'',l.date||'',l.medical?'Yes':'No'])));
  };
  draw();
}

/* ---- Tariff match ---- */
function tabTariff(el,c){
  const p=providerById(c.providerId); const m=matchClaim(c); const auto=activeVersionFor(c.providerId,c.admissionISO);
  const counts={code:0,fuzzy:0,none:0,override:0,pharmacy:0}; m.rows.forEach(r=>counts[r.method]++);
  el.innerHTML=`<div class="grid g-2-1 mb">
    <div class="card"><div class="card-head"><h3>Tariff version</h3><span class="small muted">${esc(p.name)}</span></div><div class="card-body">
      <div class="callout ${m.version?(c.tariffOverride?'warn':'info'):'bad'}"><div>${m.version?(c.tariffOverride?`<strong>Manual override:</strong> ${m.version.id} applied by analyst. Auto-selection would be ${auto?auto.id:'none'}.`:`<strong>${m.version.id}</strong> (${esc(m.version.label)}) selected automatically because the admission date <strong>${c.admission}</strong> falls within ${m.version.effectiveFrom} → ${m.version.effectiveTo||'open-ended'}.`):`<strong>No active tariff version</strong> covers admission date ${c.admission}. All medical lines are treated as uncontracted until a version is selected.`}</div></div>
      ${can('review')?`<div class="row mt"><div class="field" style="min-width:280px"><label>Apply version</label><select id="tv-sel"><option value="">Automatic (by effective date)</option>${p.versions.map(v=>`<option value="${v.id}" ${c.tariffVersionId===v.id?'selected':''}>${v.id} · ${v.effectiveFrom} → ${v.effectiveTo||'open'} · ${versionStatus(v)}</option>`).join('')}</select></div><button class="btn btn-outline" id="rematch" style="margin-top:18px">Re-run matching</button></div>`:''}
      ${m.version?`<div class="small muted mt">Discount rules in this version: ${esc(m.version.discountNote)}</div>`:''}
    </div></div>
    <div class="stack"><div class="kpi good"><div class="l">Code-first matches</div><div class="v">${counts.code+counts.override}</div><div class="d">Exact service code in schedule</div></div><div class="kpi ${counts.fuzzy?'warn':''}"><div class="l">Fuzzy matches (review)</div><div class="v">${counts.fuzzy}</div><div class="d">Description similarity ≥ ${RULES.fuzzyThreshold}%</div></div><div class="kpi ${counts.none?'bad':''}"><div class="l">Unmatched</div><div class="v">${counts.none}</div><div class="d">${counts.pharmacy} pharmacy lines matched at MRP</div></div></div>
  </div>
  <div class="card"><div class="card-head"><h3>Line-item matching</h3><span class="small muted">Best match with confidence; alternates captured for analyst review</span></div>
  <div class="table-wrap"><table class="tbl"><thead><tr><th>Bill line</th><th>Billed code</th><th class="num">Billed rate</th><th>Matched tariff item</th><th class="num">Tariff rate</th><th>Method</th><th>Confidence</th><th>Alternates / action</th></tr></thead><tbody>${m.rows.map(r=>{ const li=r.li; const diff=r.item?li.unitPrice-r.item.price:null; return `<tr class="${r.method==='none'&&li.medical?'flag':''} ${li.medical?'':'dim'}"><td>${esc(li.desc)}<div class="small muted">${esc(li.bill)} · qty ${li.qty}</div></td><td class="small">${li.code||'—'}</td><td class="num">${fmtINR(li.unitPrice)}</td><td>${r.item?esc(r.item.desc)+' <span class="small muted">('+r.item.code+')</span>':r.method==='pharmacy'?'<span class="muted">Pharmacy — MRP basis</span>':'<span class="muted">No match</span>'}</td><td class="num">${r.item?fmtINR(r.item.price)+(diff>0?` <span class="small" style="color:var(--red)">+${fmtINR(diff)}</span>`:''):'—'}</td><td><span class="badge ${{code:'b-green',override:'b-teal',fuzzy:'b-amber',none:'b-red',pharmacy:'b-gray'}[r.method]}">${{code:'Code',override:'Analyst override',fuzzy:'Fuzzy',none:'Unmatched',pharmacy:'MRP'}[r.method]}</span></td><td>${r.method==='pharmacy'?'—':confEl(r.score)}</td><td>${(r.method==='fuzzy'||r.method==='none')&&m.version&&can('review')?`<select class="btn btn-outline btn-sm" data-alt="${li.id}" style="padding:4px 8px;max-width:260px"><option value="">${r.method==='fuzzy'?'Keep fuzzy match':'Select tariff item…'}</option>${r.alternates.map(a=>`<option value="${a.item.code}">${esc(a.item.desc)} (${a.score}%)</option>`).join('')}<option value="__all">Browse full schedule…</option></select>`:r.method==='override'&&can('review')?`<button class="btn btn-ghost btn-sm" data-clear-ov="${li.id}">Clear override</button>`:'—'}</td></tr>`; }).join('')}</tbody></table></div></div>`;
  const s=$('#tv-sel',el); if(s) s.onchange=()=>{ const before=c.tariffVersionId||'auto'; c.tariffVersionId=s.value||null; c.tariffOverride=!!s.value; audit(c,'Tariff','Version '+(s.value?'overridden':'reset to automatic'),`${before} → ${s.value||'auto'}`,before,s.value||'auto'); toast('Tariff version applied — variances recomputed','ok'); render(); };
  const rm=$('#rematch',el); if(rm) rm.onclick=async()=>{ rm.disabled=true; rm.textContent='Matching…'; await sleep(600); audit(c,'Tariff','Re-matched',`${m.rows.length} lines: ${counts.code+counts.override} code, ${counts.fuzzy} fuzzy, ${counts.none} unmatched`); toast('Matching complete','ok'); render(); };
  $$('[data-alt]',el).forEach(sel=>sel.onchange=()=>{ const li=c.lineItems.find(x=>x.id===sel.dataset.alt); if(sel.value==='__all'){ openModal({title:'Select tariff item — '+li.desc, wide:true, body:`<div class="field mb"><input id="ti-q" placeholder="Search schedule…"></div><div class="table-wrap" style="max-height:360px;overflow:auto"><table class="tbl" id="ti-tbl"><tbody>${m.version.items.map(i=>`<tr class="clickable" data-code="${i.code}"><td class="id">${i.code}</td><td>${esc(i.desc)}</td><td class="small">${i.category}</td><td class="num">${fmtINR(i.price)}</td></tr>`).join('')}</tbody></table></div>`, footer:`<button class="btn btn-outline" data-close>Cancel</button>`, onOpen:mm=>{ $('#ti-q',mm).oninput=e=>{ const q=e.target.value.toLowerCase(); $$('#ti-tbl tr',mm).forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none'); }; $$('#ti-tbl tr',mm).forEach(r=>r.onclick=()=>{ setOverride(li,r.dataset.code); closeModal(); }); }}); sel.value=''; return; } if(sel.value) setOverride(li,sel.value); });
  $$('[data-clear-ov]',el).forEach(b=>b.onclick=()=>{ const li=c.lineItems.find(x=>x.id===b.dataset.clearOv); delete c.matchOverrides[li.id]; audit(c,'Tariff','Override cleared',li.desc); toast('Override removed','ok'); render(); });
  function setOverride(li,code){ const before=c.matchOverrides[li.id]||'(auto)'; c.matchOverrides[li.id]=code; audit(c,'Tariff','Match overridden',`"${li.desc}" → ${code}`,before,code); toast('Match set to '+code+' — variances recomputed','ok'); render(); }
}

/* ---- Variances ---- */
function tabVariances(el,c){
  const st=STATE.reviewSel['v'+c.id]=STATE.reviewSel['v'+c.id]||{type:'All',sev:'All',showResolved:true,open:{}};
  const focus=STATE.route.query.v; if(focus) st.open[focus]=true;
  const draw=()=>{
    const all=computeVariances(c); const t=claimTotals(c);
    const rows=all.filter(v=>(st.type==='All'||v.type===st.type)&&(st.sev==='All'||v.severity===st.sev)&&(st.showResolved||v.decision.status==='Open'));
    const bySev=s=>all.filter(v=>v.severity===s).length; const types=['All',...new Set(all.map(v=>v.type))];
    el.innerHTML=`<div class="grid g-5 mb">
      <div class="kpi"><div class="l">Total flags</div><div class="v">${all.length}</div><div class="d">${all.filter(v=>v.decision.status==='Open').length} open</div></div>
      <div class="kpi bad"><div class="l">Flagged amount</div><div class="v">${fmtINR(t.flagged)}</div><div class="d">${fmtINR(t.accepted)} accepted · ${fmtINR(t.flagged-t.accepted-t.open)} waived</div></div>
      <div class="kpi"><div class="l">Critical / High</div><div class="v">${bySev('Critical')+bySev('High')}</div><div class="d">Routed to work queue</div></div>
      <div class="kpi"><div class="l">Medium</div><div class="v">${bySev('Medium')}</div></div><div class="kpi"><div class="l">Low</div><div class="v">${bySev('Low')}</div></div>
    </div>
    <div class="card"><div class="card-head"><div class="row"><div class="seg">${types.map(x=>`<button class="${st.type===x?'active':''}" data-type="${x}">${x}</button>`).join('')}</div><div class="seg">${['All','Critical','High','Medium','Low'].map(x=>`<button class="${st.sev===x?'active':''}" data-sev="${x}">${x}</button>`).join('')}</div><label class="toggle"><input type="checkbox" id="v-res" ${st.showResolved?'checked':''}>Show decided</label></div>
      <div class="row"><button class="btn btn-outline btn-sm" id="v-export">Export</button>${can('variance')&&all.some(v=>v.decision.status==='Open')?`<button class="btn btn-primary btn-sm" id="v-accept-all">Accept all open (${all.filter(v=>v.decision.status==='Open').length})</button>`:''}</div></div>
      ${rows.length?rows.map(v=>varianceItem(v)).join(''):`<div class="empty"><strong>${all.length?'No variances match the filter':'No variances detected'}</strong>${all.length?'':'Every line item is within tariff, quantity caps and bundle rules.'}</div>`}
    </div>
    ${c.escalations.length?`<div class="card mt"><div class="card-head"><h3>Escalations</h3></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Ref</th><th>To</th><th>Reason</th><th>Raised</th><th>Status</th><th>Resolution</th></tr></thead><tbody>${c.escalations.map(e=>`<tr><td class="small">${esc(e.ref||'')}</td><td>${e.to}</td><td>${esc(e.reason)}</td><td class="small">${esc(e.by)} · ${fmtDT(e.ts)}</td><td><span class="badge ${e.status==='Open'?'b-red':'b-green'}">${e.status}</span></td><td class="small">${e.resolution?esc(e.resolution)+' — '+esc(e.resolvedBy):'—'}</td></tr>`).join('')}</tbody></table></div></div>`:''}
    ${can('claimUpdate')&&c.status!=='Updated in Claim Core'?`<div class="row mt" style="justify-content:flex-end"><button class="btn btn-accent" id="v-approve" ${t.open>0||c.escalations.some(e=>e.status==='Open')||c.docs.some(d=>d.fields.some(f=>!f.verified&&f.conf<RULES.confidenceThreshold))?'disabled':''}>Approve claim for update</button></div>${t.open>0||c.escalations.some(e=>e.status==='Open')?'<div class="small muted right mt" style="margin-top:6px">Decide all open variances and close escalations before approving.</div>':c.docs.some(d=>d.fields.some(f=>!f.verified&&f.conf<RULES.confidenceThreshold))?'<div class="small muted right" style="margin-top:6px">Validate low-confidence fields in Review & correct before approving.</div>':''}`:''}`;
    function varianceItem(v){ const d=v.decision; const open=!!st.open[v.key]; const sevC={Critical:'b-red',High:'b-red',Medium:'b-amber',Low:'b-blue'}[v.severity];
      return `<div class="vitem ${open?'open':''} ${d.status!=='Open'?'resolved':''}" data-vk="${esc(v.key)}"><div class="vhead" data-toggle="${esc(v.key)}"><svg class="chev" viewBox="0 0 24 24"><path d="m9 6 6 6-6 6"/></svg><span class="badge ${sevC}">${v.severity}</span><div class="vt"><b>${esc(v.li.desc)}</b><small>${v.type} · ${v.ruleId} · ${esc(v.li.bill)}</small></div><div class="amt"><b>${fmtINR(v.amount)}</b><small>${v.ev.pct!=null?'+'+v.ev.pct+'%':v.ev.excess!=null?'+'+v.ev.excess+' qty':'full line'}</small></div>
        <div class="row" style="flex-wrap:nowrap">${d.status==='Open'?(can('variance')?`<button class="btn btn-success btn-sm" data-acc="${esc(v.key)}">Accept deduction</button><button class="btn btn-danger btn-sm" data-rej="${esc(v.key)}">Waive</button>${can('escalate')?`<button class="btn btn-ghost btn-sm" data-esc="${esc(v.key)}">Escalate</button>`:''}`:'<span class="badge b-amber">Open</span>'):`<span class="badge ${d.status==='Accepted'?'b-green':'b-gray'}">${d.status}</span>${can('variance')?`<button class="btn btn-ghost btn-sm" data-reopen="${esc(v.key)}">Reopen</button>`:''}`}</div></div>
        <div class="vbody"><div class="vgrid">${v.ev.pct!=null?`<div><label>Billed unit price</label><span>${fmtINR(v.ev.billed)}</span></div><div><label>Contracted</label><span style="color:var(--green)">${fmtINR(v.ev.expected)}</span></div><div><label>Excess × qty</label><span style="color:var(--red)">${fmtINR(v.amount)}</span></div>`:v.ev.excess!=null?`<div><label>Billed qty</label><span>${v.ev.billed}</span></div><div><label>Allowed</label><span style="color:var(--green)">${v.ev.expected}</span></div><div><label>Excess amount</label><span style="color:var(--red)">${fmtINR(v.amount)}</span></div>`:`<div><label>Billed</label><span>${fmtINR(v.ev.billed)}</span></div><div><label>Allowed</label><span style="color:var(--green)">${fmtINR(0)}</span></div><div><label>Deductible</label><span style="color:var(--red)">${fmtINR(v.amount)}</span></div>`}<div><label>Rule</label><span style="color:var(--ink);font-size:13px">${v.ruleId}</span><div class="small muted">${esc(v.ruleName)}</div></div></div>
        <div class="evidence"><label>Rationale</label>${esc(v.rationale)}</div><div class="evidence mt" style="margin-top:8px"><label>Evidence snippet (bill line)</label><code>${esc(v.snippet)}</code></div>
        ${d.status!=='Open'?`<div class="decision"><strong>${d.status}</strong> by ${esc(d.by)} · ${fmtDT(d.ts)}${d.comment?' — '+esc(d.comment):''}</div>`:''}</div></div>`; }
    $$('[data-type]',el).forEach(b=>b.onclick=()=>{ st.type=b.dataset.type; draw(); }); $$('[data-sev]',el).forEach(b=>b.onclick=()=>{ st.sev=b.dataset.sev; draw(); }); $('#v-res',el).onchange=e=>{ st.showResolved=e.target.checked; draw(); };
    $$('[data-toggle]',el).forEach(h=>h.onclick=e=>{ if(e.target.closest('button')) return; st.open[h.dataset.toggle]=!st.open[h.dataset.toggle]; draw(); });
    const decide=(key,status,comment)=>{ const v=all.find(x=>x.key===key); c.decisions[key]={status,by:STATE.user.name,ts:new Date().toISOString(),comment}; audit(c,'Variance',status,`${v.li.desc} (${v.ruleId}) ${fmtINR(v.amount)}${comment?' — '+comment:''}`,'Open',status); };
    $$('[data-acc]',el).forEach(b=>b.onclick=()=>{ decide(b.dataset.acc,'Accepted',''); toast('Deduction accepted','ok'); afterDecision(); });
    $$('[data-rej]',el).forEach(b=>b.onclick=()=>promptModal('Waive variance','Reason for waiving (required)',v=>{ decide(b.dataset.rej,'Waived',v); toast('Variance waived','ok'); afterDecision(); },{placeholder:'e.g. Pre-approved upgrade due to non-availability of contracted room category.'}));
    $$('[data-esc]',el).forEach(b=>b.onclick=()=>{ const v=all.find(x=>x.key===b.dataset.esc); openModal({title:'Escalate variance', body:`<div class="stack"><div class="field"><label>Route to</label><select id="es-to"><option>Network Manager</option><option>Compliance</option></select></div><div class="field"><label>Reason</label><textarea id="es-why" rows="3" placeholder="What should the reviewer decide?"></textarea><div class="err" id="es-err"></div></div></div>`, footer:`<button class="btn btn-outline" data-close>Cancel</button><button class="btn btn-primary" id="es-ok">Escalate</button>`, onOpen:m=>{ $('#es-ok',m).onclick=()=>{ const why=$('#es-why',m).value.trim(); if(!why){ $('#es-err',m).textContent='A reason is required.'; return; } const to=$('#es-to',m).value; c.escalations.push({id:uid('ESC'),ts:new Date().toISOString(),by:STATE.user.name,to,reason:`${v.li.desc} (${v.ruleId}, ${fmtINR(v.amount)}): ${why}`,status:'Open',ref:v.li.desc}); c.status='Exception'; c.stage=6; audit(c,'Exception','Escalated',`${v.li.desc} → ${to}: ${why}`); notify(`Escalation: ${c.id} ${v.type.toLowerCase()} sent to ${to}`,'warn','#/queue'); closeModal(); toast('Escalated to '+to,'ok'); render(); }; }}); });
    $$('[data-reopen]',el).forEach(b=>b.onclick=()=>{ const v=all.find(x=>x.key===b.dataset.reopen); const before=c.decisions[b.dataset.reopen].status; delete c.decisions[b.dataset.reopen]; audit(c,'Variance','Reopened',`${v.li.desc} (${v.ruleId})`,before,'Open'); if(c.status==='Approved'){ c.status='Variance review'; c.stage=5; } toast('Variance reopened'); render(); });
    const aa=$('#v-accept-all',el); if(aa) aa.onclick=()=>confirmModal('Accept all open variances',`This records <strong>${all.filter(v=>v.decision.status==='Open').length}</strong> open flags totalling <strong>${fmtINR(t.open)}</strong> as accepted deductions. Each decision is audited individually.`,()=>{ all.filter(v=>v.decision.status==='Open').forEach(v=>decide(v.key,'Accepted','Bulk accept')); toast('All open variances accepted','ok'); afterDecision(); },'Accept all');
    $('#v-export',el).onclick=()=>exportCSV(c.id+'_variances.csv',[['Line item','Bill','Rule ID','Type','Severity','Amount','Billed','Expected','Decision','Decided by','Comment','Rationale']].concat(all.map(v=>[v.li.desc,v.li.bill,v.ruleId,v.type,v.severity,v.amount,v.ev.billed,v.ev.expected,v.decision.status,v.decision.by||'',v.decision.comment||'',v.rationale])));
    const ap=$('#v-approve',el); if(ap) ap.onclick=()=>confirmModal('Approve claim',`Mark <strong>${c.id}</strong> as approved with estimated payable <strong>${fmtINR(t.payable)}</strong>? It can then be pushed to Claim Core.`,()=>{ c.status='Approved'; c.stage=7; audit(c,'Claim','Approved',`Payable ${fmtINR(t.payable)}; deductions ${fmtINR(t.accepted)}`); notify(`${c.id} approved — ready for Claim Core update`,'ok','#/claims/'+c.id+'/update'); toast('Claim approved','ok'); go('#/claims/'+c.id+'/update'); },'Approve');
    function afterDecision(){ const tt=claimTotals(c); if(c.status==='Variance review'&&tt.open===0&&!c.escalations.some(e=>e.status==='Open')){ c.status=c.docs.some(d=>d.fields.some(f=>!f.verified&&f.conf<RULES.confidenceThreshold))?'In review':'Approved'; c.stage=c.status==='Approved'?7:3; if(c.status==='Approved') notify(`${c.id}: all variances decided; approved`,'ok','#/claims/'+c.id+'/update'); } render(); }
  };
  draw();
}

/* ---- Claim update (Claim Core integration) ---- */
function tabUpdate(el,c){
  const t=claimTotals(c); const cc=c.claimCore; const prim=c.diagnoses.find(d=>d.primary); const proc=c.procedures.find(p=>p.primary);
  const ready=c.status==='Approved'; const done=cc.status==='Updated';
  const payload={claimId:c.id,memberId:c.memberId,providerId:c.providerId,admissionDate:c.admissionISO,dischargeDate:c.discharge.split('-').reverse().join('-'),primaryDiagnosisICD:prim?prim.icd:null,primaryProcedurePCS:proc?proc.pcs:null,tariffVersion:(tariffVersionForClaim(c)||{}).id||null,billed:t.billed,nonMedical:t.nonMed,deductions:t.variances.filter(v=>v.decision.status==='Accepted').map(v=>({ruleId:v.ruleId,line:v.li.desc,amount:v.amount})),payable:t.payable,documents:c.docs.map(d=>({type:d.type,pages:d.pages.length,validated:d.validated}))};
  el.innerHTML=`<div class="grid g-3-2">
    <div class="card"><div class="card-head"><h3>Digitized payload → Claim Core</h3><span class="small muted">POST /claims/${c.id}/digitized</span></div><div class="card-body">
      <dl class="kv mb"><dt>Status</dt><dd>${done?'<span class="badge b-teal">Updated in Claim Core</span>':ready?'<span class="badge b-green">Approved — ready to push</span>':`<span class="badge b-amber">Not ready</span> <span class="small muted">claim status is ${esc(c.status)}</span>`}</dd><dt>Idempotency key</dt><dd class="small mono">${cc.idempotencyKey||'—'}</dd><dt>Attempts</dt><dd>${cc.attempts}</dd><dt>Last sync</dt><dd>${cc.lastSync?fmtDT(cc.lastSync):'—'}</dd><dt>Reconciliation</dt><dd>${cc.reconciled?'<span class="badge b-green">Reconciled</span>':done?'<span class="badge b-amber">Pending (24h job)</span>':'—'}</dd></dl>
      <pre class="code" style="max-height:300px">${esc(JSON.stringify(payload,null,2))}</pre>
      ${can('claimUpdate')?`<div class="row mt" style="justify-content:flex-end"><button class="btn btn-outline" id="cc-recon" ${!done||cc.reconciled?'disabled':''}>Run reconciliation</button><button class="btn btn-accent" id="cc-push" ${!ready||done?'disabled':''}>${done?'Already updated':'Push to Claim Core'}</button></div>${done?'<div class="small muted right" style="margin-top:6px">Duplicate posting is prevented by the idempotency key.</div>':!ready?'<div class="small muted right" style="margin-top:6px">Approve the claim from the Variances tab first.</div>':''}`:`<div class="callout warn mt"><div>Only Team Leads and Admins can push updates to Claim Core.</div></div>`}
    </div></div>
    <div class="card"><div class="card-head"><h3>Integration log</h3><span class="small muted">Retries with exponential backoff</span></div>${cc.history.length?`<div class="table-wrap"><table class="tbl"><thead><tr><th>Time</th><th>Attempt</th><th>Code</th><th>Result</th></tr></thead><tbody>${cc.history.map(h=>`<tr><td class="small mono">${fmtDT(h.ts)}</td><td>${h.attempt}</td><td><span class="badge ${h.code===200?'b-green':'b-red'}">${h.code}</span></td><td class="small">${esc(h.msg)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>No attempts yet</strong>The log will show each HTTP attempt, including retries.</div>'}</div>
  </div>`;
  const push=$('#cc-push',el); if(push) push.onclick=async()=>{ push.disabled=true; push.textContent='Pushing…'; cc.idempotencyKey=cc.idempotencyKey||('idem-'+c.id.slice(-5)+'-'+Math.random().toString(16).slice(2,6)); const fail=cc.attempts===0; cc.attempts++; cc.history.push({ts:new Date().toISOString(),attempt:cc.attempts,code:fail?502:200,msg:fail?'Bad Gateway — upstream returned invalid response; retrying in 1 s':'OK — claim updated'}); tabUpdate(el,c); if(fail){ toast('502 from Claim Core — retrying with backoff','warn'); await sleep(1000); cc.attempts++; cc.history.push({ts:new Date().toISOString(),attempt:cc.attempts,code:200,msg:'OK — claim updated (retry 1)'}); } cc.status='Updated'; cc.lastSync=new Date().toISOString(); c.status='Updated in Claim Core'; c.stage=8; audit(c,'Claim Core','Updated',`POST /claims/${c.id}/digitized → 200 OK (attempt ${cc.attempts}) idem=${cc.idempotencyKey}`); notify(`${c.id} updated in Claim Core (payable ${fmtINR(t.payable)})`,'ok','#/claims/'+c.id+'/update'); toast('Claim Core updated','ok'); render(); };
  const rc=$('#cc-recon',el); if(rc) rc.onclick=async()=>{ rc.disabled=true; rc.textContent='Reconciling…'; await sleep(800); cc.reconciled=true; audit(c,'Claim Core','Reconciled','Payable and deductions match Claim Core record'); toast('Reconciled — no discrepancies','ok'); render(); };
}

/* ---- Audit trail ---- */
function tabAudit(el,c){
  el.innerHTML=`<div class="card"><div class="card-head"><h3>Audit trail</h3><span class="small muted">Every edit, override and decision with before/after, user and timestamp</span><button class="btn btn-outline btn-sm" id="exp-audit">Export CSV</button></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Timestamp</th><th>User</th><th>Entity</th><th>Action</th><th>Detail</th><th>Before → After</th></tr></thead><tbody>${c.audit.map(a=>`<tr><td class="small mono">${fmtDT(a.ts)}</td><td>${esc(a.user)}</td><td>${esc(a.entity)}</td><td><span class="badge b-gray">${esc(a.action)}</span></td><td class="small">${esc(a.detail)}</td><td>${a.before!=null||a.after!=null?`<div class="diff"><div class="b">${esc(a.before??'—')}</div><div class="a">${esc(a.after??'—')}</div></div>`:'<span class="muted">—</span>'}</td></tr>`).join('')}</tbody></table></div></div>`;
  $('#exp-audit',el).onclick=()=>exportCSV(c.id+'_audit.csv',[['Timestamp','User','Entity','Action','Detail','Before','After']].concat(c.audit.map(a=>[a.ts,a.user,a.entity,a.action,a.detail,a.before??'',a.after??''])));
}

/* ---- Boot ---- */
renderUserBox();
if(!location.hash) location.hash='#/intake';
render();
setInterval(()=>{ if(document.visibilityState==='visible' && !$('#modal-bg').classList.contains('open')) renderNav(); }, 60000);
